settings.liquid:
{%- comment -%}
CURVJEANS — Social Proof Badge (With Divider)
{%- endcomment -%}
{%- liquid
assign _lc = request.locale.iso_code | downcase
case _lc
  when "nl"
    assign spt = "Geliefd door <strong>20.000+</strong> vrouwen"
  when "de"
    assign spt = "Geliebt von <strong>20.000+</strong> Frauen"
  else
    assign spt = "Worn & Loved by <strong>20,000+</strong> women"
endcase
-%}
<div class="cj-spb-section">
  <div class="cj-spb-wrapper">
    <span>{{ spt }}</span>
    <img class="cj-spb-verified"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878"
         alt="verified">
  </div>
  <div class="cj-spb-divider"></div>
</div>
<style>
.cj-spb-section {
  background: #fff;
}
.cj-spb-wrapper {
  text-align: center;
  padding: 20px 16px 16px;
  font-size: 14px;
  font-weight: 500;
  color: #666;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 4px;
}
.cj-spb-wrapper strong {
  font-weight: 700;
  color: #333;
}
.cj-spb-verified {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.cj-spb-divider {
  width: 60px;
  height: 1px;
  background: #e0e0e0;
  margin: 0 auto 20px;
}
@media (max-width: 640px) {
  .cj-spb-wrapper {
    font-size: 13px;
    padding: 16px 16px 12px;
  }
  .cj-spb-divider {
    margin-bottom: 0px;
  }
}
</style>
